IF (NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.[ROUTINES] WHERE SPECIFIC_SCHEMA = 'relation' AND SPECIFIC_NAME = 'BulkUpsert')) BEGIN CREATE procedure [relation].[BulkUpsert] @uid uniqueidentifier, @r int as begin set nocount on;
declare @st varchar(50), @stid int, @ot varchar(50), @otid int, @it int
select @st = Subject, @stid = SubjectID, @ot = Object, @otid = ObjectID, @it = ID from IntersectType where [uid] = @uid
update T set T.FieldTypeID = S.ID from #RelationshipFieldTable T inner join FieldType S on S.Object = 'IntersectType' and S.ObjectID = @it and S.Name = T.FieldName
BEGIN
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship is missing key field(s): [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name, ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it and FT.IsPartOfKey = 1 left join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID where F.ItemNumber is null group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship is missing required field(s): [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name, ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it and FT.IsRequired = 1 left join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID where F.ItemNumber is null group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.LookupValue = S.[Value] from #RelationshipFieldTable T inner join FieldType F on F.ID = T.FieldTypeID and F.[Type] = 'Lookup' inner join FieldLookupValue S on S.FieldTypeID = F.ID and S.[Text] = T.FieldValue
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship contains one or more fields with invalid lookup values: [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name+'='+F.FieldValue, ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it and FT.[Type] = 'Lookup' inner join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID and F.LookupValue is null group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship contains one or more field that are invalid based on their data types: [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name + ' is ' + FT.[Type] + ' but has a value of ' + F.FieldValue, ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it inner join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID and ( (FT.[Type] = 'Boolean' and LOWER(F.FieldValue) not in ('false', 'true')) or (FT.[Type] = 'Date' and ISDATE(F.FieldValue) = 0) or (FT.[Type] = 'DateTime' and ISDATE(F.FieldValue) = 0) or (FT.[Type] = 'Number' and ISNUMERIC(F.FieldValue + '.e0') = 0) or (FT.[Type] = 'Decimal' and ISNUMERIC(F.FieldValue) = 0) or (FT.[Type] = 'Link' and (CHARINDEX('|', F.FieldValue, 0) = 0 OR CHARINDEX('|', F.FieldValue, 0) is null) ) or (FT.[Type] = 'Percentage' and ISDATE(F.FieldValue) = 0) ) group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship contains one or more field that have an invalid length: [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name + ' must have an exact length of ' + cast(FT.[Length] as nvarchar), ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it inner join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID and FT.[Length] is not null and FT.[Length] <> LEN(F.FieldValue) group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship contains one or more field that have an invalid minimum length: [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name + ' must have a minimum length of ' + cast(FT.[MinimumLength] as nvarchar), ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it inner join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID and FT.[MinimumLength] is not null and FT.[MinimumLength] > LEN(F.FieldValue) group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
update T set T.Success = 0, T.[Message] = coalesce(T.[Message] + '; ', '') + 'Relationship contains one or more field that have an invalid maximum length: [' + S.Names + ']' from #RelationshipTable T inner join ( select A.ItemNumber, STRING_AGG(FT.Name + ' must have a maximum length of ' + cast(FT.[MaximumLength] as nvarchar), ', ') as Names from #RelationshipTable A inner join FieldType FT on FT.Object = 'IntersectType' and FT.ObjectID = @it inner join #RelationshipFieldTable F on F.ItemNumber = A.ItemNumber and F.FieldTypeID = FT.ID and FT.[MaximumLength] is not null and FT.[MaximumLength] < LEN(F.FieldValue) group by A.ItemNumber ) S on S.ItemNumber = T.ItemNumber;
END
drop table if exists #ObjectMergeTableResult; create table #ObjectMergeTableResult (ID int, ItemNumber int, [Action] nvarchar(10)); CREATE NONCLUSTERED INDEX IX_TempObjectMergeTableResult ON #ObjectMergeTableResult ( ItemNumber ASC );
update T set T.Subject = S.Object, T.SubjectID = S.ObjectID, T.Object = O.Object, T.ObjectID = O.ObjectID from #RelationshipTable T left join AssetWithType S on S.[Type] = @st and S.TypeID = @stid and S.[uid] = T.SubjectUid left join AssetWithType O on O.[Type] = @ot and O.TypeID = @otid and O.[uid] = T.ObjectUid;
update T set T.Subject = S.Object, T.SubjectID = S.ObjectID from #RelationshipTable T inner join AssetType S on @st = 'ReferenceItemType' and @stid = 0 and S.[uid] = T.SubjectUid and T.Subject is null;
update T set T.Object = O.Object, T.ObjectID = O.ObjectID from #RelationshipTable T inner join AssetType O on @ot = 'ReferenceItemType' and @otid = 0 and O.[uid] = T.ObjectUid and T.Object is null;
update #RelationshipTable set Success = 0, [Message] = coalesce([Message] + '; ', '') + 'Not able to resolve subject of this relationship to a valid asset.' where Subject is null or SubjectID is null;
update #RelationshipTable set Success = 0, [Message] = coalesce([Message] + '; ', '') + 'Not able to resolve object of this relationship to a valid asset.' where Object is null or ObjectID is null;
merge into [Intersect] T using ( select * from #RelationshipTable where Success is null ) S on ( T.IntersectTypeID = @it and T.Subject = S.Subject and T.SubjectID = S.SubjectID and T.Object = S.Object and T.ObjectID = S.ObjectID ) when matched then update set T.UpdatedBy = @r, T.UpdatedOn = getutcdate() when not matched by target then insert (IntersectTypeID, Subject, SubjectID, Object, ObjectID, [State], CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) values (@it, S.Subject, S.SubjectID, S.Object, S.ObjectID, 1, @r, getutcdate(), @r, getutcdate(), 'BULK_API') output inserted.ID, S.ItemNumber, $action into #ObjectMergeTableResult;
update T set T.IntersectID = S.ID, T.IsNew = IIF(S.[Action] = 'I', 1, 0) from #RelationshipTable T inner join #ObjectMergeTableResult S on S.ItemNumber = T.ItemNumber;
merge into Field T using ( select distinct A.IntersectID as ObjectID, F.FieldTypeID, coalesce(F.LookupValue, F.FieldValue) as Value from #RelationshipFieldTable F inner join #RelationshipTable A on A.ItemNumber = F.ItemNumber and A.ObjectID is not null and F.FieldTypeID is not null and A.Success is null ) S on ( T.FieldTypeID = S.FieldTypeID and T.ObjectType = 'Intersect' and T.ObjectID = S.ObjectID ) when matched then update set T.Value = S.Value when not matched by target then insert (FieldTypeID, ObjectType, ObjectID, Value) values (S.FieldTypeID, 'Intersect', S.ObjectID, S.Value);
update #RelationshipTable set Success = 1 where Success is null and IntersectID is not null; end END
